선형 검색
리스트의 처음부터 끝까지 하나씩 확인하며 원하는 값을 찾는 가장 단순한 검색 방법입니다.
import Foundation

func linearSearch&lt;T: Equatable&gt;(_ array: [T], _ object: T) -&gt; Int? {
  for (index, obj) in array.enumerated() where obj == object {
    return index
  }
  return nil
}

